target.css:
:root {
  --ink: #24332f;
  --paper: #fffdf7;
  --mint: #cbe7d8;
  --coral: #f4846b;
  --line: #b5d2c5;
}

.visit-card {
  box-sizing: border-box;
  width: 480px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.visit-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 13px 16px;
  background: var(--mint);
  border-bottom: 1px solid var(--line);
}

.pet-mark {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  font-size: 21px;
  background: var(--paper);
  border-radius: 12px;
}

.title-block {
  flex: 1;
}

.title-block h1 {
  margin: 0;
  font-size: 18px;
  font-weight: 750;
  line-height: 1.15;
}

.title-block p {
  margin: 3px 0 0;
  font-size: 12px;
}

.status {
  padding: 5px 9px;
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
  background: var(--coral);
  border-radius: 999px;
}

.profile {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 13px 16px;
}

.portrait {
  display: grid;
  place-items: center;
  width: 56px;
  height: 56px;
  margin: 0;
  font-size: 28px;
  background: var(--mint);
  border-radius: 50%;
}

.pet-info h2 {
  margin: 0;
  font-size: 16px;
  line-height: 1.15;
}

.pet-info p {
  margin: 4px 0 7px;
  font-size: 12px;
}

.traits {
  display: flex;
  gap: 5px;
  padding: 0;
  margin: 0;
  list-style: none;
}

.traits li {
  padding: 3px 7px;
  font-size: 11px;
  font-weight: 650;
  border: 1px solid var(--line);
  border-radius: 999px;
}

.details {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.detail {
  padding: 9px 16px;
  margin: 0;
  border-right: 1px solid var(--line);
}

.detail:last-child {
  border-right: 0;
}

.detail span,
.detail strong {
  display: block;
}

.detail span {
  margin-bottom: 3px;
  font-size: 10px;
  font-weight: 700;
  line-height: 1;
}

.detail strong {
  font-size: 12px;
  line-height: 1.15;
}

.visit-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
}

.visit-footer p {
  margin: 0;
  font-size: 12px;
}

.visit-footer button {
  padding: 7px 11px;
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
  background: var(--ink);
  border: 0;
  border-radius: 8px;
}

